L000015	\title{Structural Order Drives Diffusion in a Granular Packing}
L000016	
L000017	\author{David Luce}
L000018	\affiliation{LEMTA, Université de Lorraine, CNRS, 2, Avenue de la Forêt de Haye, Vandœuvre-lès-Nancy, 54504, France}
